files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

.page {
  display: grid;
  grid-template-columns: 55% 45%;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  line-height: 25px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

/* Используя desktop first задайте поведение для блока .page при ширине меньше 656px */

.page__header {
  grid-column: 2 / -1;
  grid-row: 1 / 2;
  padding: 50px;
  font-weight: 800;
  font-size: 38px;
  line-height: 39px;
  text-align: center;
  text-transform: uppercase;
  background-color: #ffc802;
}

.page__img {
  grid-column: 1 / 2;
  grid-row: 2 / 3;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.page__quote {
  grid-column: 2 / -1;
  grid-row: 2 / 3;
  padding: 30px;
  background-color: #fff;
}

.page__cite {
  grid-column: -1 / -2;
  grid-row: -1 / -2;
  padding: 30px;
  background-color: #ffc802;
}

@media (max-width: 656px) {
  .page {
    display: flex;
    flex-direction: column;
  }
}
